 PERFORM pg_temp.m1_11_add_check('M1_11_POS_69_COMPONENT_HASH','Component set hash',(SELECT component_hash FROM _m1_11_vhash),(SELECT component_hash=stored_component_hash FROM _m1_11_vhash),'stored hash','Component set hash reconciles.');
 PERFORM pg_temp.m1_11_add_check('M1_11_POS_70_COMBINED_HASH','Combined set hash',(SELECT combined_hash FROM _m1_11_vhash),(SELECT combined_hash=stored_combined_hash FROM _m1_11_vhash),'stored hash','Combined set hash reconciles.');
 PERFORM pg_temp.m1_11_add_check('M1_11_POS_71_GENERATION_EVIDENCE','Generation evidence completeness',(SELECT count(*)::text FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m1_11_vctx) AND evidence_code IN ('M1_11_GENERATION_SPEC','M1_11_SNAPSHOT_ENTITY_COUNT','M1_11_COMPONENT_ENTITY_COUNT','M1_11_CANONICAL_ENTITY_COUNT','M1_11_CANONICAL_MISMATCH_COUNT','M1_11_SNAPSHOT_SET_HASH','M1_11_COMPONENT_SET_HASH','M1_11_COMBINED_SET_HASH','M1_11_GENERATION_SUMMARY')),(SELECT count(*)=9 FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m1_11_vctx) AND evidence_code IN ('M1_11_GENERATION_SPEC','M1_11_SNAPSHOT_ENTITY_COUNT','M1_11_COMPONENT_ENTITY_COUNT','M1_11_CANONICAL_ENTITY_COUNT','M1_11_CANONICAL_MISMATCH_COUNT','M1_11_SNAPSHOT_SET_HASH','M1_11_COMPONENT_SET_HASH','M1_11_COMBINED_SET_HASH','M1_11_GENERATION_SUMMARY')),'9','All governed generation evidence is persisted.');
 PERFORM pg_temp.m1_11_add_check('M1_11_POS_72_STAGE_BOUNDARY','Stage boundaries and blocking errors',(SELECT (downstream_rows+blocking_errors)::text FROM _m1_11_vboundary),(SELECT downstream_rows=0 AND blocking_errors=0 FROM _m1_11_vboundary),'0','No downstream risk/decision output or blocking error exists.');
END $checks$;
/* 6. Persist final validation evidence */
INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_text,unit_code,status,interpretation)
SELECT (SELECT run_id FROM _m1_11_vctx),evidence_code,'PORTFOLIO',metric_name,observed_value,'TEXT',status,interpretation FROM _m1_11_validation
ON CONFLICT(run_id,evidence_code,segment_key) DO UPDATE SET metric_name=EXCLUDED.metric_name,metric_value_text=EXCLUDED.metric_value_text,metric_value_numeric=NULL,unit_code=EXCLUDED.unit_code,status=EXCLUDED.status,interpretation=EXCLUDED.interpretation,created_at=clock_timestamp();
/* 7. Advance the governed run state */
UPDATE msbf_ctl.run_registry SET run_status=CASE WHEN (SELECT count(*) FROM _m1_11_validation)=72 AND (SELECT count(*) FROM _m1_11_validation WHERE status='PASS')=72 THEN 'M1_11_VALIDATED' ELSE 'M1_11_FAILED' END,
 notes=coalesce(notes,'')||E'\nM1.11 v0.2R2 positive validation: '||(SELECT count(*) FROM _m1_11_validation WHERE status='PASS')||'/72 PASS.'
WHERE run_id=(SELECT run_id FROM _m1_11_vctx);
/* 8. Commit and return one session-filterable result set */
COMMIT;
SELECT evidence_code,metric_name,observed_value,threshold_value,status,interpretation FROM _m1_11_validation ORDER BY evidence_code;
